/* ==========================================================================
   Nixora Services LLC — form endpoint (single-file build).

   Generated by worker/scripts/bundle.js from src/email.js, src/forms.js and
   src/index.js. Do not edit this file: edit those and rebuild, or the next
   build will overwrite whatever was changed here.

   This is the file to paste into the Cloudflare dashboard editor when
   deploying without a terminal. See worker/README.md.
   ========================================================================== */

/* ==========================================================================
   Nixora Services LLC — notification email rendering.

   Tables and inline styles only: Gmail and Outlook strip <style> blocks,
   flexbox and grid. 600px is the width every client renders without
   horizontal scrolling, and the logo is a hosted PNG because most clients
   refuse to draw SVG.
   ========================================================================== */

const NAVY = '#054a8b';
const INK = '#0e1626';
const MUTED = '#5d6b82';
const LINE = '#eef2f7';
const TINT = '#f4f7fb';
const LIME = '#57741b';

function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/* Turns a typed phone number into a dialable href. US numbers arrive as
   (314) 555-0000; anything already carrying a + is left alone. */
function telHref(phone) {
  const raw = String(phone || '').trim();
  if (!raw) return '';
  if (raw.charAt(0) === '+') return raw.replace(/[^\d+]/g, '');
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  return digits.length === 10 ? '+1' + digits : '+' + digits;
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

/* Formats the YYYY-MM-DD that <input type="date"> submits. Parsed by hand
   rather than through Date, which would shift the day across time zones. */
function formatDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || '').trim());
  if (!match) return String(value || '');
  const month = MONTHS[Number(match[2]) - 1];
  if (!month) return value;
  return month + ' ' + Number(match[3]) + ', ' + match[1];
}

const label = (text) =>
  `<p style="margin:0 0 10px;font-size:12px;font-weight:700;letter-spacing:1.3px;` +
  `text-transform:uppercase;color:${NAVY};">${escapeHtml(text)}</p>`;

const cell = (style) =>
  `padding:9px 0;border-bottom:1px solid ${LINE};${style || ''}`;

/* A label/value table. `html` is already-escaped markup so a value can carry
   a link or a line break. */
function rowsTable(rows) {
  const body = rows.map(([name, html]) =>
    `<tr><td style="${cell('width:180px;color:' + MUTED + ';')}">${escapeHtml(name)}</td>` +
    `<td style="${cell()}">${html}</td></tr>`
  ).join('');

  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="font-size:15px;color:${INK};border-collapse:collapse;">${body}</table>`;
}

/* Ticked declarations. The tick is an entity rather than an emoji so it keeps
   its colour, and the sentence still reads if a client drops the glyph. */
function checksTable(items) {
  const last = items.length - 1;
  const body = items.map((item, i) => {
    const pad = i === 0 ? '14px 16px 4px'
      : i === last ? '4px 16px 14px'
        : '4px 16px';
    return `<tr><td style="padding:${pad};">` +
      `<span style="color:${LIME};font-weight:700;">&#10003;</span>&nbsp; ${escapeHtml(item)}</td></tr>`;
  }).join('');

  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="font-size:14px;color:#33425c;background-color:${TINT};border-radius:10px;">${body}</table>`;
}

function messageBlock(text) {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="background-color:${TINT};border-radius:10px;">
    <tr><td style="padding:16px;font-size:15px;line-height:1.6;color:${INK};">
      ${escapeHtml(text).replace(/\r?\n/g, '<br>')}
    </td></tr></table>`;
}

function section(block) {
  let inner = '';
  if (block.rows) inner = rowsTable(block.rows);
  else if (block.checks) inner = checksTable(block.checks);
  else if (block.text) inner = messageBlock(block.text);
  else return '';

  return `<tr><td style="padding:26px 32px 0;">${label(block.title)}${inner}</td></tr>`;
}

function buttons(actions) {
  if (!actions.length) return '';
  const html = actions.map((action, i) => {
    const style = i === 0
      ? `display:inline-block;background-color:${NAVY};color:#ffffff;text-decoration:none;` +
        `font-size:15px;font-weight:700;padding:12px 22px;border-radius:100px;`
      : `display:inline-block;margin-left:8px;color:${NAVY};text-decoration:none;` +
        `font-size:15px;font-weight:700;padding:12px 18px;border:1.5px solid #dee4ee;border-radius:100px;`;
    return `<a href="${escapeHtml(action.href)}" style="${style}">${escapeHtml(action.text)}</a>`;
  }).join('\n              ');

  return `<p style="margin:18px 0 0;">\n              ${html}\n            </p>`;
}

/**
 * Renders the notification body.
 *
 * spec: { eyebrow, title, subtitle, actions[], sections[], signature, footer,
 *         siteUrl, logoUrl }
 */
function renderEmail(spec) {
  const sections = (spec.sections || []).map(section).join('\n');

  // Without a signature block the last section would sit flush against the
  // footer, so an empty row supplies the missing bottom margin.
  const spacer = spec.signature
    ? ''
    : `<tr><td style="height:30px;line-height:30px;font-size:0;">&nbsp;</td></tr>`;

  const signature = spec.signature
    ? `<tr><td style="padding:22px 32px 30px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
                 style="border-top:2px solid ${LINE};">
            <tr><td style="padding:16px 0 0;font-size:14px;color:${MUTED};">
              Signed electronically by
              <strong style="color:${INK};">${escapeHtml(spec.signature.name)}</strong>
              on ${escapeHtml(formatDate(spec.signature.date))}
            </td></tr>
          </table>
        </td></tr>`
    : '';

  return `<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(spec.eyebrow)}</title></head>
<body style="margin:0;padding:0;background-color:${LINE};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
       style="margin:0;padding:0;background-color:#eef2f7;">
  <tr>
    <td align="center" style="padding:24px 12px;">

      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"
             style="width:600px;max-width:100%;background-color:#ffffff;border-radius:12px;overflow:hidden;
                    font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">

        <!-- Header. The alt text is styled white so it still reads on the
             navy band in clients that block images by default. -->
        <tr>
          <td style="background-color:${NAVY};padding:26px 32px;">
            <img src="${escapeHtml(spec.logoUrl)}" width="150" height="73" alt="Nixora Services"
                 style="display:block;border:0;outline:none;text-decoration:none;height:auto;
                        color:#ffffff;font-family:Arial,Helvetica,sans-serif;font-size:20px;
                        font-weight:700;">
            <p style="margin:16px 0 0;font-size:13px;line-height:1.4;color:#b3d2ef;
                      letter-spacing:1.4px;text-transform:uppercase;font-weight:700;">
              ${escapeHtml(spec.eyebrow)}
            </p>
          </td>
        </tr>

        <tr>
          <td style="padding:30px 32px 8px;">
            <h1 style="margin:0 0 6px;font-size:26px;line-height:1.25;color:${INK};font-weight:700;">
              ${escapeHtml(spec.title)}
            </h1>
            <p style="margin:0;font-size:16px;line-height:1.5;color:${MUTED};">
              ${spec.subtitle}
            </p>
            ${buttons(spec.actions || [])}
          </td>
        </tr>

${sections}
${signature}${spacer}

        <tr>
          <td style="background-color:${TINT};padding:18px 32px;font-size:12px;line-height:1.6;color:${MUTED};">
            ${spec.footer}
          </td>
        </tr>

      </table>
    </td>
  </tr>
</table>
</body></html>`;
}

/* Plain-text alternative. Every notification ships with one: it is what
   deliverability filters look for, and what a watch or a screen reader gets. */
function renderText(spec) {
  const lines = [spec.eyebrow.toUpperCase(), '', spec.title, spec.subtitleText, ''];

  (spec.sections || []).forEach((block) => {
    lines.push(block.title.toUpperCase());
    if (block.rows) block.rows.forEach(([name, , plain]) => lines.push('  ' + name + ': ' + plain));
    else if (block.checks) block.checks.forEach((item) => lines.push('  [x] ' + item));
    else if (block.text) lines.push('  ' + block.text.replace(/\r?\n/g, '\n  '));
    lines.push('');
  });

  if (spec.signature) {
    lines.push('Signed electronically by ' + spec.signature.name +
      ' on ' + formatDate(spec.signature.date), '');
  }

  lines.push(spec.footerText);
  return lines.join('\n');
}

/* ==========================================================================
   Nixora Services LLC — turning a submitted form into a notification.

   One module per concern: this one knows the field names used by the site's
   three forms, email.js knows how to draw them, index.js moves the request.
   ========================================================================== */

/* Field names as they appear in the HTML. Kept here so a rename on the site
   is a one-line change rather than a hunt through the renderer. */
const A = {
  position: 'Position Applied For',
  name: 'Full Name',
  email: 'email',
  phone: 'Phone',
  dob: 'Date of Birth',
  street: 'Street Address',
  unit: 'Apt or Unit',
  city: 'City',
  state: 'State',
  zip: 'ZIP Code',
  ecName: 'Emergency Contact',
  ecPhone: 'Emergency Phone',
  ecRelation: 'Emergency Relationship',
  experience: 'Cleaning Experience',
  availability: 'Availability',
  shifts: 'Shifts Available',
  notes: 'Experience Notes',
  resume: 'Resume Link',
  signature: 'Electronic Signature',
  signedOn: 'Signed On'
};

const DECLARATIONS = [
  ['Certified Accurate', 'Certified the information is accurate'],
  ['Accepted SMS and WhatsApp', 'Accepted SMS and WhatsApp updates'],
  ['Accepted Digital Data Handling', 'Accepted digital handling of their data'],
  ['Accepted Background and Drug Screening', 'Accepted background check and drug screening']
];

/* Reads a form value, trimmed, never undefined. */
const get = (form, key) => String(form.get(key) || '').trim();

const firstName = (full) => String(full || '').trim().split(/\s+/)[0] || 'the applicant';

const mailLink = (address) =>
  `<a href="mailto:${escapeHtml(address)}" style="color:#054a8b;">${escapeHtml(address)}</a>`;

const urlLink = (href) =>
  `<a href="${escapeHtml(href)}" style="color:#054a8b;">${escapeHtml(href)}</a>`;

/* Drops rows whose value came back empty, so an optional field the applicant
   skipped leaves no blank line in the email. */
const rows = (list) => list.filter(([, , plain]) => plain);

const textRow = (name, value) => [name, escapeHtml(value), value];

const STARS = (rating) => {
  const n = Math.max(0, Math.min(5, Number(rating) || 0));
  return '★'.repeat(n) + '☆'.repeat(5 - n);
};

/* ------------------------------------------------------------------ */

function applicationSpec(form) {
  const name = get(form, A.name);
  const email = get(form, A.email);
  const phone = get(form, A.phone);
  const position = get(form, A.position);

  const cityLine = [get(form, A.city), get(form, A.state)].filter(Boolean).join(', ');
  // The unit goes on the street line, the way it is written on an envelope.
  const streetLine = [get(form, A.street), get(form, A.unit)].filter(Boolean).join(', ');
  const address = [streetLine, [cityLine, get(form, A.zip)].filter(Boolean).join(' ')]
    .filter(Boolean);

  const emergency = [get(form, A.ecName), get(form, A.ecPhone)].filter(Boolean).join(' · ');
  const relation = get(form, A.ecRelation);

  const schedule = [get(form, A.availability), get(form, A.shifts)]
    .filter(Boolean).join(' · ');

  const actions = [];
  if (email) actions.push({ href: 'mailto:' + email, text: 'Reply to ' + firstName(name) });
  if (telHref(phone)) actions.push({ href: 'tel:' + telHref(phone), text: phone });

  const checks = DECLARATIONS
    .filter(([field]) => get(form, field))
    .map(([, sentence]) => sentence);

  const sections = [
    {
      title: 'Applicant',
      rows: rows([
        ['Email', email ? mailLink(email) : '', email],
        // Also in the table, not only on the button above: a number inside a
        // tel: link cannot be selected with the cursor, and it gets copied
        // and pasted elsewhere more often than it gets tapped.
        textRow('Phone', phone),
        textRow('Date of birth', formatDate(get(form, A.dob))),
        ['Address', address.map(escapeHtml).join('<br>'), address.join(', ')],
        ['Emergency contact',
          escapeHtml(emergency) + (relation ? ` <span style="color:#5d6b82;">(${escapeHtml(relation)})</span>` : ''),
          emergency + (relation ? ' (' + relation + ')' : '')]
      ])
    },
    {
      title: 'Availability',
      rows: rows([
        textRow('Experience', get(form, A.experience)),
        textRow('Schedule', schedule),
        textRow('Notes', get(form, A.notes)),
        ['Resume', get(form, A.resume) ? urlLink(get(form, A.resume)) : '', get(form, A.resume)]
      ])
    }
  ];

  if (checks.length) sections.push({ title: 'Declarations', checks });

  const signatureName = get(form, A.signature);

  return {
    subject: position ? `${name} applied — ${position}` : `${name} applied`,
    replyTo: email,
    eyebrow: 'New job application',
    title: name,
    subtitle: `applied for <strong style="color:#054a8b;">${escapeHtml(position)}</strong>`,
    subtitleText: 'applied for ' + position,
    actions,
    sections,
    signature: signatureName
      ? { name: signatureName, date: get(form, A.signedOn) }
      : null,
    page: 'apply.html',
    formName: 'application form',
    footerNote: 'Replying to this email goes straight to the applicant.'
  };
}

function contactSpec(form) {
  const name = get(form, 'name');
  const email = get(form, 'email');
  const phone = get(form, 'Phone');
  const service = get(form, 'Service Needed');
  const company = get(form, 'Company');

  const actions = [];
  if (email) actions.push({ href: 'mailto:' + email, text: 'Reply to ' + firstName(name) });
  if (telHref(phone)) actions.push({ href: 'tel:' + telHref(phone), text: phone });

  return {
    subject: `${name} — new service request`,
    replyTo: email,
    eyebrow: 'New service request',
    title: name,
    subtitle: service
      ? `is asking about <strong style="color:#054a8b;">${escapeHtml(service)}</strong>`
      : 'wrote in through the contact form',
    subtitleText: service ? 'is asking about ' + service : 'wrote in through the contact form',
    actions,
    sections: [
      {
        title: 'Contact',
        rows: rows([
          ['Email', email ? mailLink(email) : '', email],
          textRow('Phone', phone),
          textRow('Company', company),
          textRow('Service needed', service)
        ])
      },
      { title: 'Message', text: get(form, 'Message') }
    ],
    signature: null,
    page: '#contact',
    formName: 'contact form',
    footerNote: 'Replying to this email goes straight to the sender.'
  };
}

function reviewSpec(form) {
  const name = get(form, 'name');
  const rating = get(form, 'Rating');
  const type = get(form, 'Reviewer Type');
  const consent = get(form, 'Consented To Publish');

  return {
    subject: `${name} left a ${rating}-star review`,
    replyTo: '',
    eyebrow: 'New website review',
    title: name,
    subtitle: `left a <strong style="color:#054a8b;">${escapeHtml(rating)}-star review</strong> ` +
      `<span style="color:#d9922c;">${STARS(rating)}</span>`,
    subtitleText: 'left a ' + rating + '-star review',
    actions: [],
    sections: [
      {
        title: 'Reviewer',
        rows: rows([
          textRow('Name', name),
          textRow('Reviewer type', type),
          textRow('Rating', rating ? rating + ' of 5  ' + STARS(rating) : '')
        ])
      },
      { title: 'Review', text: get(form, 'Message') },
      {
        title: 'Permission',
        checks: [consent
          ? 'Allowed Nixora Services to publish this review with their first name and role'
          : 'Did NOT allow this review to be published — keep it internal']
      }
    ],
    signature: null,
    page: '#feedback',
    formName: 'feedback form',
    footerNote: 'The reviewer did not leave an email address, so this thread cannot be replied to.'
  };
}

const BUILDERS = {
  application: applicationSpec,
  contact: contactSpec,
  review: reviewSpec
};

/* Trusts the hidden _form field, and works out the type from the fields
   themselves when it is missing — a submission should never be lost to a
   markup slip. */
function detectFormType(form) {
  const declared = get(form, '_form').toLowerCase();
  if (BUILDERS[declared]) return declared;
  if (form.get(A.position)) return 'application';
  if (form.get('Rating')) return 'review';
  return 'contact';
}

function buildSpec(form, type) {
  const build = BUILDERS[type] || contactSpec;
  const spec = build(form);

  // A submission with no name would produce an empty subject line, so fall
  // back to something an inbox can still sort on.
  if (!spec.title) {
    spec.title = 'Website submission';
    spec.subject = spec.eyebrow + ' — Nixora Services';
  }
  return spec;
}

/* ------------------------------------------------------------------
   Spreadsheet rows

   A different shape from the email. The email leaves out what the person
   skipped; a spreadsheet column has to appear on every row or the table
   stops lining up, so these carry every field whether or not it was filled,
   in a fixed order.
   ------------------------------------------------------------------ */

const yesNo = (form, field) => (get(form, field) ? 'Yes' : 'No');

const SHEET_ROWS = {
  application: (form) => [
    ['Position', get(form, A.position)],
    ['Full Name', get(form, A.name)],
    ['Email', get(form, A.email)],
    ['Phone', get(form, A.phone)],
    ['Date of Birth', formatDate(get(form, A.dob))],
    ['Street Address', get(form, A.street)],
    ['Apt or Unit', get(form, A.unit)],
    ['City', get(form, A.city)],
    ['State', get(form, A.state)],
    ['ZIP Code', get(form, A.zip)],
    ['Emergency Contact', get(form, A.ecName)],
    ['Emergency Phone', get(form, A.ecPhone)],
    ['Emergency Relationship', get(form, A.ecRelation)],
    ['Experience', get(form, A.experience)],
    ['Availability', get(form, A.availability)],
    ['Shifts', get(form, A.shifts)],
    ['Notes', get(form, A.notes)],
    ['Resume Link', get(form, A.resume)],
    ['Certified Accurate', yesNo(form, 'Certified Accurate')],
    ['Accepted SMS and WhatsApp', yesNo(form, 'Accepted SMS and WhatsApp')],
    ['Accepted Data Handling', yesNo(form, 'Accepted Digital Data Handling')],
    ['Accepted Background Check', yesNo(form, 'Accepted Background and Drug Screening')],
    ['Electronic Signature', get(form, A.signature)],
    ['Signed On', formatDate(get(form, A.signedOn))]
  ],

  contact: (form) => [
    ['Name', get(form, 'name')],
    ['Company', get(form, 'Company')],
    ['Email', get(form, 'email')],
    ['Phone', get(form, 'Phone')],
    ['Service Needed', get(form, 'Service Needed')],
    ['Message', get(form, 'Message')]
  ],

  review: (form) => [
    ['Name', get(form, 'name')],
    ['Reviewer Type', get(form, 'Reviewer Type')],
    ['Rating', get(form, 'Rating')],
    ['Review', get(form, 'Message')],
    ['May Publish', yesNo(form, 'Consented To Publish')]
  ]
};

/* The tab each form writes to. Named for a person reading the file, not for
   the code. */
const SHEET_TABS = {
  application: 'Applications',
  contact: 'Contact Requests',
  review: 'Reviews'
};

function sheetRow(form, type) {
  const build = SHEET_ROWS[type] || SHEET_ROWS.contact;
  const columns = ['Received'];
  const values = [new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC'];

  build(form).forEach(([column, value]) => {
    columns.push(column);
    values.push(value);
  });

  return { tab: SHEET_TABS[type] || SHEET_TABS.contact, columns, values };
}

/* ==========================================================================
   Nixora Services LLC — address autocomplete.

   The page never sees the Google key. It asks this Worker, and the Worker
   asks Google, which means the key lives as a secret next to the Resend one
   rather than in the page source where anyone can read it off a browser's
   view-source and spend the company's Maps quota.

   It also keeps Google's script off the site: no third-party JavaScript, and
   nothing loaded before someone actually starts typing an address.
   ========================================================================== */

const AUTOCOMPLETE = 'https://places.googleapis.com/v1/places:autocomplete';
const DETAILS = 'https://places.googleapis.com/v1/places/';

/* Two calls made in the same session are billed as one lookup, so the page
   generates a token when someone starts typing and sends it back when they
   pick a result. */
const body = (input, sessionToken) => ({
  input,
  regionCode: 'US',
  includedRegionCodes: ['us'],
  includedPrimaryTypes: ['street_address', 'subpremise', 'premise'],
  ...(sessionToken ? { sessionToken } : {})
});

async function callGoogle(url, key, init) {
  const response = await fetch(url, {
    ...init,
    headers: { 'content-type': 'application/json', 'X-Goog-Api-Key': key, ...(init.headers || {}) }
  });
  const text = await response.text();
  if (!response.ok) {
    let message = text;
    try { message = (JSON.parse(text).error || {}).message || text; } catch (ignored) { /* raw */ }
    const error = new Error('Places responded ' + response.status + ': ' + message);
    error.status = response.status;
    error.detail = String(message).slice(0, 300);
    throw error;
  }
  return JSON.parse(text || '{}');
}

async function suggest(env, input, sessionToken) {
  const key = String(env.GOOGLE_PLACES_KEY || '').trim();
  if (!key) return { configured: false, suggestions: [] };

  const data = await callGoogle(AUTOCOMPLETE, key, {
    method: 'POST',
    body: JSON.stringify(body(input, sessionToken))
  });

  const suggestions = (data.suggestions || [])
    .map((s) => s.placePrediction)
    .filter(Boolean)
    .slice(0, 5)
    .map((p) => ({
      id: p.placeId,
      // The main text is the street line; the rest is the city and state.
      line: (p.structuredFormat && p.structuredFormat.mainText &&
             p.structuredFormat.mainText.text) || (p.text && p.text.text) || '',
      context: (p.structuredFormat && p.structuredFormat.secondaryText &&
                p.structuredFormat.secondaryText.text) || ''
    }))
    .filter((s) => s.line);

  return { configured: true, suggestions };
}

/* Google returns the address in pieces; the form wants four fields. */
const COMPONENT = (components, type) => {
  const hit = components.find((c) => (c.types || []).indexOf(type) !== -1);
  return hit ? { long: hit.longText || '', short: hit.shortText || '' } : { long: '', short: '' };
};

async function details(env, placeId, sessionToken) {
  const key = String(env.GOOGLE_PLACES_KEY || '').trim();
  if (!key) return { configured: false };

  const url = DETAILS + encodeURIComponent(placeId) +
    (sessionToken ? '?sessionToken=' + encodeURIComponent(sessionToken) : '');

  const data = await callGoogle(url, key, {
    method: 'GET',
    headers: { 'X-Goog-FieldMask': 'addressComponents,formattedAddress' }
  });

  const parts = data.addressComponents || [];
  const number = COMPONENT(parts, 'street_number').long;
  // The abbreviated form of the street: "Market St", not "Market Street".
  // That is how an address is written on an envelope, and what Google's own
  // formatted address uses.
  const route = COMPONENT(parts, 'route');
  const street = route.short || route.long;
  const unit = COMPONENT(parts, 'subpremise').long;

  return {
    configured: true,
    address: {
      street: [number, street].filter(Boolean).join(' ') + (unit ? ' ' + unit : ''),
      // Some addresses carry no city, only the township that stands in for one.
      city: COMPONENT(parts, 'locality').long ||
            COMPONENT(parts, 'sublocality').long ||
            COMPONENT(parts, 'administrative_area_level_3').long,
      state: COMPONENT(parts, 'administrative_area_level_1').short,
      zip: COMPONENT(parts, 'postal_code').long,
      formatted: data.formattedAddress || ''
    }
  };
}

/* ==========================================================================
   Nixora Services LLC — address verification without an account.

   Two free public services, neither of which needs a key, a project or a
   card:

     · the US Census Bureau geocoder, for checking that a street address
       exists and getting its standardised form
     · Zippopotam, for turning a ZIP code into a city and state

   This is the fallback for Google Places, and it also runs alongside it:
   Places suggests while someone types, this checks what they ended up with.
   Both are conveniences. Every failure here answers "unknown" rather than an
   error, so an unreachable service costs a hint and never an application.
   ========================================================================== */

const CENSUS = 'https://geocoding.geo.census.gov/geocoder/locations/onelineaddress';
const ZIPS = 'https://api.zippopotam.us/us/';

/* The Census answers in capitals — "10 MARKET ST, SAINT LOUIS, MO". Shouting
   an address back at someone reads like a correction even when it is not, so
   it is title-cased before it is shown. */
const KEEP_UPPER = ['NE', 'NW', 'SE', 'SW', 'N', 'S', 'E', 'W', 'US', 'PO'];

function titleCase(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/\b[a-z']+\b/g, (word) => word.charAt(0).toUpperCase() + word.slice(1))
    .split(' ')
    .map((word) => (KEEP_UPPER.indexOf(word.toUpperCase()) !== -1 ? word.toUpperCase() : word))
    .join(' ');
}

const withTimeout = (ms) => {
  // A slow public service must not hold up the form. AbortSignal.timeout is
  // not everywhere yet, so the controller is wired by hand.
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  return { signal: controller.signal, done: () => clearTimeout(timer) };
};

async function lookupZip(zip) {
  const clean = String(zip || '').trim().slice(0, 5);
  if (!/^\d{5}$/.test(clean)) return { found: false };

  const t = withTimeout(4000);
  try {
    const response = await fetch(ZIPS + clean, { signal: t.signal });
    if (!response.ok) return { found: false };

    const data = await response.json();
    const place = (data.places || [])[0];
    if (!place) return { found: false };

    return {
      found: true,
      city: place['place name'] || '',
      state: place['state abbreviation'] || ''
    };
  } catch (error) {
    return { found: false };
  } finally {
    t.done();
  }
}

async function verifyAddress({ street, city, state, zip }) {
  const line = [street, [city, state].filter(Boolean).join(', '), zip]
    .filter(Boolean).join(', ').trim();
  if (!street || line.length < 8) return { checked: false };

  const url = CENSUS + '?address=' + encodeURIComponent(line) +
    '&benchmark=Public_AR_Current&format=json';

  const t = withTimeout(6000);
  try {
    const response = await fetch(url, { signal: t.signal });
    if (!response.ok) return { checked: false };

    const data = await response.json();
    const match = (((data.result || {}).addressMatches) || [])[0];

    // No match is not "wrong". New construction, rural routes and recently
    // renumbered streets are all missing from the file, so this reports that
    // it could not confirm rather than that the address is bad.
    if (!match) return { checked: true, verified: false };

    const parts = match.addressComponents || {};
    const number = [parts.fromAddress].filter(Boolean).join('');
    const streetName = [parts.preDirection, parts.preType, parts.streetName,
      parts.suffixType, parts.suffixDirection].filter(Boolean).join(' ');

    return {
      checked: true,
      verified: true,
      address: {
        street: titleCase([number, streetName].filter(Boolean).join(' ')),
        city: titleCase(parts.city || ''),
        state: (parts.state || '').toUpperCase(),
        zip: parts.zip || '',
        formatted: titleCase(match.matchedAddress || '')
          .replace(/\b([a-z]{2}),/i, (m, s) => s.toUpperCase() + ',')
      }
    };
  } catch (error) {
    return { checked: false };
  } finally {
    t.done();
  }
}

/* ==========================================================================
   Nixora Services LLC — is this address able to receive mail at all?

   Two free checks, in order of certainty:

     · the domain has MX records, so mail sent there has somewhere to go
     · the domain is not a near-miss of a common one (gmial.com, hotmial.com)

   Neither proves the mailbox exists. Nothing does, short of sending to it or
   paying a verification service — so this catches the mistyped domain, which
   is where most bounces come from, and says nothing about the part before
   the @.
   ========================================================================== */

const DOH = 'https://cloudflare-dns.com/dns-query';

/* Domains people mean, and the misspellings that reach them as bounces.
   Only near-misses of addresses that are typed thousands of times a day —
   a general-purpose spell checker would start "correcting" real domains. */
const COMMON = [
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'live.com', 'icloud.com', 'me.com', 'aol.com', 'comcast.net', 'att.net',
  'sbcglobal.net', 'verizon.net', 'msn.com', 'protonmail.com'
];

/* Levenshtein, bounded: anything more than two edits away is a different
   domain rather than a typo of this one. */
function editDistance(a, b, limit) {
  if (Math.abs(a.length - b.length) > limit) return limit + 1;

  let previous = Array.from({ length: b.length + 1 }, (unused, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const current = [i];
    let best = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      current[j] = Math.min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost);
      if (current[j] < best) best = current[j];
    }
    if (best > limit) return limit + 1;
    previous = current;
  }
  return previous[b.length];
}

function suggestDomain(domain) {
  const clean = String(domain || '').toLowerCase();
  if (!clean || COMMON.indexOf(clean) !== -1) return '';

  for (const candidate of COMMON) {
    if (editDistance(clean, candidate, 2) <= 2) return candidate;
  }
  return '';
}

async function checkEmail(address) {
  const value = String(address || '').trim().toLowerCase();
  const match = /^[^\s@]+@([^\s@]+\.[^\s@]+)$/.exec(value);
  if (!match) return { checked: false };

  const domain = match[1];
  const suggestion = suggestDomain(domain);

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4000);
  try {
    const response = await fetch(
      DOH + '?name=' + encodeURIComponent(domain) + '&type=MX',
      { headers: { accept: 'application/dns-json' }, signal: controller.signal }
    );
    if (!response.ok) return { checked: false, suggestion };

    const data = await response.json();
    // Status 3 is NXDOMAIN: the domain itself does not exist.
    const exists = data.Status === 0;
    const mx = (data.Answer || []).filter((record) => record.type === 15);

    // Some domains take mail on the A record with no MX. Rare, and worth not
    // rejecting someone over, so it counts as deliverable.
    const hasMail = mx.length > 0 || (exists && !data.Answer);

    return {
      checked: true,
      domain,
      exists,
      deliverable: exists && (mx.length > 0 || hasMail),
      mxCount: mx.length,
      suggestion
    };
  } catch (error) {
    // A DNS lookup that did not answer is not evidence against the address.
    return { checked: false, suggestion };
  } finally {
    clearTimeout(timer);
  }
}

/* ==========================================================================
   Nixora Services LLC — proving an applicant owns the email they typed.

   A code is emailed and typed back. Nothing is stored anywhere: the code is
   signed, and the signature is what travels to the browser and back. The
   browser never holds the code — that only ever reaches the inbox — and
   cannot check a guess without the signing key, so guesses have to be made
   one network round trip at a time.

   The signing key is derived from the Resend key rather than configured
   separately, so this needs no new setting. It is a derivation, not the key
   itself: holding it reveals nothing about the account it came from. Set
   VERIFY_SECRET to use something else.
   ========================================================================== */

const CODE_MINUTES = 15;      // long enough to go and look, short enough to expire
const PROOF_HOURS = 3;        // long enough to finish a long application form

const encoder = new TextEncoder();

const b64url = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes)))
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

async function signingKey(env) {
  const base = String(env.VERIFY_SECRET || '').trim() ||
    'derived:' + String(env.RESEND_API_KEY || '').trim();

  return crypto.subtle.importKey(
    'raw', encoder.encode(base), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
}

async function sign(env, parts) {
  const key = await signingKey(env);
  return b64url(await crypto.subtle.sign('HMAC', key, encoder.encode(parts.join('|'))));
}

/* Compares without leaking, through timing, how much of the value matched. */
function sameString(a, b) {
  const left = String(a || '');
  const right = String(b || '');
  if (left.length !== right.length) return false;

  let difference = 0;
  for (let i = 0; i < left.length; i++) {
    difference |= left.charCodeAt(i) ^ right.charCodeAt(i);
  }
  return difference === 0;
}

const normalizeEmail = (value) => String(value || '').trim().toLowerCase();

/* Six digits, drawn from the system's random source rather than Math.random.
   Short enough to read off a phone and type, and a guess still costs a round
   trip against an endpoint that answers one at a time. */
function makeCode() {
  const bytes = crypto.getRandomValues(new Uint32Array(1));
  return String(bytes[0] % 1000000).padStart(6, '0');
}

async function makeChallenge(env, email, code) {
  const expires = Date.now() + CODE_MINUTES * 60 * 1000;
  const signature = await sign(env, ['code', normalizeEmail(email), code, String(expires)]);
  return expires + '.' + signature;
}

async function checkChallenge(env, email, code, challenge) {
  const parts = String(challenge || '').split('.');
  if (parts.length !== 2) return { ok: false, reason: 'malformed' };

  const expires = Number(parts[0]);
  if (!expires || Date.now() > expires) return { ok: false, reason: 'expired' };

  const expected = await sign(env, ['code', normalizeEmail(email), String(code || ''), parts[0]]);
  if (!sameString(expected, parts[1])) return { ok: false, reason: 'wrong' };

  return { ok: true };
}

/* What the form carries once the code has been accepted. Tied to the address
   it was issued for, so it cannot be moved to a different one. */
async function makeProof(env, email) {
  const expires = Date.now() + PROOF_HOURS * 60 * 60 * 1000;
  const signature = await sign(env, ['proof', normalizeEmail(email), String(expires)]);
  return expires + '.' + signature;
}

async function checkProof(env, email, proof) {
  const parts = String(proof || '').split('.');
  if (parts.length !== 2) return { ok: false, reason: 'missing' };

  const expires = Number(parts[0]);
  if (!expires || Date.now() > expires) return { ok: false, reason: 'expired' };

  const expected = await sign(env, ['proof', normalizeEmail(email), parts[0]]);
  if (!sameString(expected, parts[1])) return { ok: false, reason: 'mismatch' };

  return { ok: true };
}

/* ==========================================================================
   Nixora Services LLC — form endpoint.

   Receives the three site forms, renders a branded notification and hands it
   to Resend. It replaces Formspree so the subject line, the layout and the
   sending address all belong to Nixora rather than to a third party.

   Configuration lives in wrangler.toml ([vars]); the Resend key is a secret:
     npx wrangler secret put RESEND_API_KEY
   ========================================================================== */

const RESEND_ENDPOINT = 'https://api.resend.com/emails';

/* Stamped on every response the Worker makes about itself. Deploying through
   the dashboard editor is easy to get wrong in a way that leaves the previous
   version running and says nothing, which cost two rounds of fixing code that
   was never live. Bump this whenever src/ changes. */
const BUILD = '2026-09-15.7';

// A job application with long notes is a few kilobytes. Anything past this is
// not a person filling in a form.
const MAX_BODY_BYTES = 128 * 1024;

const json = (body, status, headers) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...headers }
  });

/* An origin is a scheme, host and port — never a path, never a trailing
   slash, never uppercase. Normalising both sides means a setting typed as
   "https://www.nixoraservices.com/" still matches, rather than refusing every
   submission from the site it was meant to allow. */
const normalizeOrigin = (value) =>
  String(value || '').trim().toLowerCase().replace(/\/+$/, '');

function allowedOrigins(env) {
  return String(env.ALLOWED_ORIGINS || '')
    .split(',')
    .map(normalizeOrigin)
    .filter(Boolean);
}

const originAllowed = (request, env) =>
  allowedOrigins(env).indexOf(normalizeOrigin(request.headers.get('Origin'))) !== -1;

/* Echoes the origin back when it is on the list. A refusal still carries the
   header, so the page can read why it was refused: the request was already
   turned away, and the reason is the site's own public address. Without it the
   browser hides the response and all anyone sees is an opaque CORS failure. */
function corsHeaders(request, env) {
  const origin = request.headers.get('Origin');
  const headers = { 'vary': 'Origin' };
  if (origin) {
    headers['access-control-allow-origin'] = origin;
    headers['access-control-allow-methods'] = 'POST, OPTIONS';
    headers['access-control-allow-headers'] = 'Content-Type, Accept';
    headers['access-control-max-age'] = '86400';
  }
  return headers;
}

/* The site posts with fetch and asks for JSON. A browser that fell back to a
   plain form POST gets sent to the thank-you page instead. */
const wantsJson = (request) =>
  String(request.headers.get('Accept') || '').indexOf('application/json') !== -1;

function recipient(env, type) {
  const perForm = {
    application: env.TO_APPLICATIONS,
    contact: env.TO_CONTACT,
    review: env.TO_REVIEWS
  }[type];
  return String(perForm || env.TO_EMAIL || '').trim();
}

async function readForm(request) {
  const contentType = String(request.headers.get('Content-Type') || '');
  if (contentType.indexOf('application/json') !== -1) {
    const body = await request.json();
    const form = new FormData();
    Object.keys(body || {}).forEach((key) => form.append(key, String(body[key])));
    return form;
  }
  return request.formData();
}

/* Keys get pasted with a stray space, a newline, wrapping quotes, or the word
   Bearer already in front. Every one of those reaches Resend as an invalid key
   and comes back as a validation error that says nothing about whitespace, so
   they are stripped here rather than diagnosed twice. */
const cleanKey = (value) =>
  String(value || '')
    .trim()
    .replace(/^["']|["']$/g, '')
    .replace(/^Bearer\s+/i, '')
    .trim();

async function send(env, { to, replyTo, subject, html, text }) {
  const payload = {
    from: env.FROM_EMAIL,
    to: [to],
    subject,
    html,
    text
  };
  if (replyTo) payload.reply_to = replyTo;

  const response = await fetch(RESEND_ENDPOINT, {
    method: 'POST',
    headers: {
      authorization: 'Bearer ' + cleanKey(env.RESEND_API_KEY),
      'content-type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const body = await response.text();
    // Resend answers with { message } on a rejection. Keep that sentence on
    // the error: it names the actual problem — an unverified domain, a
    // malformed from address, a key without sending access — where the status
    // code alone would only say "it did not work".
    let message = body;
    try {
      const parsed = JSON.parse(body);
      if (parsed && parsed.message) message = parsed.message;
    } catch (ignored) { /* not JSON — keep the raw body */ }

    const error = new Error('Resend responded ' + response.status + ': ' + message);
    error.detail = String(message).slice(0, 300);
    error.status = response.status;
    throw error;
  }
  return response.json();
}

/* GET /selftest — answers "is this thing configured correctly" without
   sending anything. Diagnosing a rejected send otherwise means reading the
   Worker's log, which is the hardest place to reach for the person who has to
   act on what it says; this is a URL you can open in a browser.

   It reports what is set, never what it is set to, with one exception: the
   addresses, which are printed on the website anyway. The key is described --
   present, length, plausible prefix -- and never echoed. */
/* Appends the submission to the Google Sheet, when one is configured.

   This runs after the email has already gone. A spreadsheet that did not get
   its row is worth knowing about, but it is not worth failing a job
   application over, so a failure here is logged and reported through the
   self-test rather than shown to the person who filled in the form. */
/* Apps Script answers a POST with a 302 to where the result is waiting, and
   following a 302 turns the request into a GET — which lands on doGet, which
   this script does not define. So doPost ran, the row was written, and the
   Worker read back an error page for a call that had already succeeded.

   The redirect is followed by hand instead: POST once, then GET the location
   the way Apps Script intends. */
async function postToAppsScript(endpoint, payload) {
  const posted = await fetch(endpoint, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload)
  });

  // A redirect is the success signal, and the only reliable one. Apps Script
  // redirects to where the output is waiting *after* doPost has run to
  // completion; a script that threw answers 200 with an error page instead,
  // and a deployment that cannot be reached answers 403 or 404. So the status
  // of this first response already says whether the row was written.
  if (posted.status >= 300 && posted.status < 400) {
    const location = posted.headers.get('location');
    const result = { status: 200, body: '{"ok":true}', redirected: true };
    if (!location) return result;

    // The body is worth having when it can be had — it carries the script's
    // own {ok:false, error} for a row it declined, such as a bad token. But
    // that second hop is a one-use URL and sometimes 404s by the time it is
    // asked for, which says nothing about whether doPost succeeded.
    try {
      const echoed = await fetch(location, { method: 'GET' });
      const body = (await echoed.text()).slice(0, 300);
      if (echoed.ok && /"ok"\s*:/.test(body)) return { status: 200, body, redirected: true };
    } catch (ignored) { /* the redirect already told us what we needed */ }

    return result;
  }

  return { status: posted.status, body: (await posted.text()).slice(0, 300) };
}

async function appendToSheet(env, form, type) {
  const endpoint = String(env.SHEET_WEBHOOK_URL || '').trim();
  if (!endpoint) return { configured: false };

  const row = sheetRow(form, type);
  const answer = await postToAppsScript(endpoint,
    { token: String(env.SHEET_TOKEN || ''), ...row });

  // Apps Script answers 200 with an HTML error page when the script itself
  // threw, so the status alone does not settle it.
  const ok = answer.status < 400 && /"ok"\s*:\s*true/.test(answer.body);
  if (!ok) throw new Error('Sheet responded ' + answer.status + ': ' + answer.body);
  return { configured: true, ok: true, tab: row.tab };
}

/* Writes one row to a tab of its own, so the answer to "is the spreadsheet
   still there" does not depend on reading a log, and does not put a fake
   applicant among the real ones. */
async function trySheet(env) {
  const endpoint = String(env.SHEET_WEBHOOK_URL || '').trim();
  if (!endpoint) return { configured: false };

  const answer = await postToAppsScript(endpoint, {
    token: String(env.SHEET_TOKEN || ''),
    tab: 'Endpoint tests',
    columns: ['Received', 'Note'],
    values: [new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC',
             'Written by /selftest?sheet=1. Nobody filled in a form.']
  });

  const ok = answer.status < 400 && /"ok"\s*:\s*true/.test(answer.body);
  return { configured: true, ok, status: answer.status, answer: answer.body };
}

/* Everything the self-test can read is correct and the send still fails, so
   the only thing left to look at is what Resend says when it is actually asked
   to send. This performs one real send to the configured recipient -- never to
   an address from the request -- and reports the answer verbatim. */
async function trySending(env) {
  const to = recipient(env, 'contact');
  try {
    await send(env, {
      to,
      replyTo: '',
      subject: 'Nixora Services — endpoint test',
      html: '<p>This is the form endpoint testing itself. Nobody filled in a form.</p>',
      text: 'This is the form endpoint testing itself. Nobody filled in a form.'
    });
    return { attempted: true, ok: true, to, note: 'Resend accepted it. Check ' + to + '.' };
  } catch (error) {
    return {
      attempted: true,
      ok: false,
      to,
      status: error && error.status,
      message: error && error.detail ? error.detail : String(error && error.message || '')
    };
  }
}

async function selftest(env, options) {
  const key = cleanKey(env.RESEND_API_KEY);
  const report = {
    build: BUILD,
    settings: {
      SITE_URL: env.SITE_URL || null,
      FROM_EMAIL: env.FROM_EMAIL || null,
      TO_EMAIL: recipient(env, 'contact') || null,
      ALLOWED_ORIGINS: allowedOrigins(env)
    },
    key: {
      present: Boolean(key),
      length: key.length,
      startsWithRe: key.slice(0, 3) === 're_',
      hadStrayCharacters: key !== String(env.RESEND_API_KEY || '')
    }
  };

  if (!key) {
    report.verdict = 'RESEND_API_KEY is empty. Add it as a Secret and deploy again.';
    return report;
  }

  // Described, never echoed — the same treatment the Resend key gets. A key
  // that is the wrong length or has the wrong prefix is a key from another
  // project, or one that lost characters on the way into the dashboard, and
  // neither is visible from "API key not valid".
  const placesKey = String(env.GOOGLE_PLACES_KEY || '').trim();
  report.places = {
    configured: Boolean(placesKey),
    keyLength: placesKey.length,
    startsWithAIza: placesKey.slice(0, 4) === 'AIza',
    expectedLength: 39
  };

  // ?places=1 runs one real lookup and reports Google's answer verbatim.
  // Whether the key works, whether the right API is enabled and whether
  // billing is on all fail differently, and only Google can say which.
  if (options && options.places) {
    if (!report.places.configured) {
      report.verdict = 'GOOGLE_PLACES_KEY is not set, so the address field is a ' +
        'plain text box. That is a working state, not a fault.';
      return report;
    }
    try {
      const result = await suggest(env, '1 Market St, St. Louis', 'selftest-session');
      report.places.matches = result.suggestions.length;
      report.places.example = result.suggestions[0] || null;
      report.verdict = result.suggestions.length
        ? 'Address lookup works. ' + result.suggestions.length + ' matches for a St. Louis address.'
        : 'Google accepted the key but returned nothing, which usually means the ' +
          'wrong Places API is enabled — it has to be Places API (New).';
    } catch (error) {
      report.places.status = error && error.status;
      report.places.message = error && error.detail;

      // "API key not valid" says nothing about which of its causes applies,
      // so the shape of what was stored is reported alongside it.
      const shape = report.places.startsWithAIza && report.places.keyLength === 39
        ? 'The stored key has the right shape, so it is more likely the wrong ' +
          'key — one from a deleted project, or from a project where Places API ' +
          '(New) is not enabled. A key created in the last few minutes can also ' +
          'need a little longer.'
        : 'The stored key does not look like a Google key: it is ' +
          report.places.keyLength + ' characters and ' +
          (report.places.startsWithAIza ? 'starts with AIza' : 'does not start with AIza') +
          ', where a Google key is 39 and does. Whatever is in GOOGLE_PLACES_KEY ' +
          'is not the key you copied.';

      report.verdict = 'Google refused the lookup: ' + (error && error.detail) + ' — ' + shape;
    }
    return report;
  }
  report.sheet = { configured: Boolean(String(env.SHEET_WEBHOOK_URL || '').trim()) };
  if (report.sheet.configured) {
    report.sheet.tokenSet = Boolean(String(env.SHEET_TOKEN || '').trim());
  }

  if (options && options.sheet) {
    if (!report.sheet.configured) {
      report.verdict = 'SHEET_WEBHOOK_URL is empty, so nothing is being written ' +
        'to a spreadsheet. The email is unaffected.';
      return report;
    }
    try {
      const attempt = await trySheet(env);
      report.sheet.test = attempt;
      // These fail differently and are fixed differently, so they are told
      // apart rather than lumped together as "something is wrong with the
      // sheet". A 404 in particular sends people hunting for a permission
      // problem that is not there.
      const signIn = /accounts\.google\.com|ServiceLogin|sign in to continue/i
        .test(attempt.answer);
      const html = /^\s*<!doctype html|^\s*<html/i.test(attempt.answer);

      report.verdict = attempt.ok
        ? 'The spreadsheet accepted a row. Look for a tab called "Endpoint tests".'
        : attempt.status === 404
          ? 'The script URL no longer exists (404). The spreadsheet or its Web App ' +
            'deployment has been deleted, so SHEET_WEBHOOK_URL points at nothing. ' +
            'It needs setting up again, and the new /exec URL stored here.'
          : attempt.status === 403
            ? 'The deployment exists but refuses this request (403). That is what ' +
              '"Who has access" set to anything other than "Anyone" does: the Worker ' +
              'arrives signed in as nobody. Edit the existing deployment rather than ' +
              'making a new one, so the URL stays the same.'
            : signIn
            ? 'The script answered with a sign-in page, which means the Web App is ' +
              'no longer deployed for "Anyone". Redeploy it with that access.'
            : html
              ? 'The script answered with an error page (' + attempt.status + '), which ' +
                'is what Apps Script returns when the script itself threw. Open the ' +
                'script and check its executions.'
              : 'The script refused the row (' + attempt.status + '): ' + attempt.answer;
    } catch (error) {
      report.sheet.test = { ok: false, error: String(error && error.message).slice(0, 200) };
      report.verdict = 'Could not reach the script at all: ' + (error && error.message);
    }
    return report;
  }

  if (options && options.send) {
    report.send = await trySending(env);
    report.verdict = report.send.ok
      ? 'Sent. If it does not arrive, the problem is delivery rather than ' +
        'configuration — look in spam, then at the Resend dashboard.'
      : 'Resend refused the send: ' + report.send.message;
    return report;
  }

  // Asking Resend for the domain list is the cheapest way to find out whether
  // it accepts the key at all, and where the key is allowed to read them it
  // doubles as a check that the address the Worker sends from belongs to a
  // domain that is actually verified.
  //
  // A sending-only key cannot read that list, and Resend refuses it with a 401
  // that says so. That refusal is the right answer for this endpoint -- it is
  // proof the key is real and scoped exactly as it should be -- so it must not
  // be reported as a broken key.
  let response;
  try {
    response = await fetch('https://api.resend.com/domains', {
      headers: { authorization: 'Bearer ' + key }
    });
  } catch (error) {
    report.verdict = 'Could not reach Resend: ' + (error && error.message);
    return report;
  }

  const body = await response.text();
  report.resend = { status: response.status };

  if (response.status === 401 || response.status === 403 || response.status === 400) {
    let message = body;
    try { message = (JSON.parse(body) || {}).message || body; } catch (ignored) { /* raw */ }
    message = String(message).slice(0, 200);
    report.resend.message = message;

    if (/restricted to only send/i.test(message)) {
      report.resend.keyScope = 'sending only';
      report.verdict = 'The key is valid and scoped to sending, which is what this ' +
        'endpoint needs. A key like that cannot read the domain list, so whether ' +
        'the sending domain is verified has to be checked in the Resend dashboard. ' +
        'Submit the form to test the rest.';
      return report;
    }

    report.verdict = 'Resend refuses this API key. Create a new one with Sending ' +
      'access and replace RESEND_API_KEY.';
    return report;
  }

  if (!response.ok) {
    report.resend.message = body.slice(0, 200);
    report.verdict = 'Resend answered ' + response.status + '.';
    return report;
  }

  let domains = [];
  try {
    const parsed = JSON.parse(body);
    domains = (parsed.data || parsed || []).map((d) => ({ name: d.name, status: d.status }));
  } catch (ignored) { /* leave empty */ }
  report.resend.domains = domains;

  const match = /@([^>\s]+)>?\s*$/.exec(String(env.FROM_EMAIL || ''));
  const sendingDomain = match ? match[1].toLowerCase() : null;
  const verified = domains.some((d) =>
    d.name && d.name.toLowerCase() === sendingDomain && String(d.status).toLowerCase() === 'verified');

  report.verdict = !sendingDomain
    ? 'FROM_EMAIL does not contain a readable address. It should look like: ' +
      'Nixora Services <notifications@nixoraservices.com>'
    : verified
      ? 'All good. The key works and ' + sendingDomain + ' is verified for sending.'
      : 'The key works, but ' + sendingDomain + ' is not listed as verified in this ' +
        'Resend account. Check FROM_EMAIL against the domains above.';
  return report;
}

/* The code email. Deliberately plain: the code is the whole message, and it
   has to be readable at a glance on a phone held in the other hand. */
function codeEmail(env, code, siteUrl) {
  return {
    eyebrow: 'Email verification',
    title: code,
    subtitle: 'is your code for the Nixora Services application form. ' +
      'It is good for 15 minutes.',
    subtitleText: 'is your code for the Nixora Services application form. ' +
      'It is good for 15 minutes.',
    actions: [],
    sections: [],
    signature: null,
    logoUrl: siteUrl + '/assets/img/mail-logo.png',
    footer: 'If you did not start an application at ' +
      '<a href="' + escapeHtml(siteUrl) + '/apply.html" style="color:#054a8b;">nixoraservices.com</a>, ' +
      'you can ignore this email — nothing was submitted.',
    footerText: 'If you did not start an application at ' + siteUrl +
      '/apply.html, you can ignore this email — nothing was submitted.'
  };
}

export default {
  async fetch(request, env) {
    const cors = corsHeaders(request, env);

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: cors });
    }

    const origin = request.headers.get('Origin');
    const url = new URL(request.url);

    /* Address lookup. Both paths are POST because the site posts JSON to
       them; a failure answers 200 with an empty list rather than an error,
       so a Google outage or a spent quota costs the applicant a convenience
       and never the ability to type their own address. */
    if (url.pathname === '/places/suggest' || url.pathname === '/places/details') {
      if (request.method !== 'POST') {
        return json({ ok: false, error: 'Send this with POST.' }, 405, cors);
      }
      if (origin && !originAllowed(request, env)) {
        return json({ ok: false, error: 'Origin not allowed.' }, 403, cors);
      }

      let payload = {};
      try { payload = await request.json(); } catch (ignored) { /* empty */ }

      try {
        if (url.pathname === '/places/suggest') {
          const input = String(payload.input || '').trim();
          if (input.length < 4) return json({ ok: true, suggestions: [] }, 200, cors);
          const result = await suggest(env, input, payload.sessionToken);
          return json({ ok: true, ...result }, 200, cors);
        }
        const result = await details(env, String(payload.placeId || ''), payload.sessionToken);
        return json({ ok: true, ...result }, 200, cors);
      } catch (error) {
        console.error('Places lookup failed:', error && error.message);
        return json({ ok: false, suggestions: [], detail: error && error.detail }, 200, cors);
      }
    }

    /* Address help that needs no account: a ZIP turned into a city and state,
       and a typed address checked against the US Census file. Both answer
       "unknown" rather than an error when the public service is unreachable,
       so the form is never held up by one. */
    if (url.pathname === '/address/zip' || url.pathname === '/address/verify') {
      if (request.method !== 'POST') {
        return json({ ok: false, error: 'Send this with POST.' }, 405, cors);
      }
      if (origin && !originAllowed(request, env)) {
        return json({ ok: false, error: 'Origin not allowed.' }, 403, cors);
      }

      let payload = {};
      try { payload = await request.json(); } catch (ignored) { /* empty */ }

      const result = url.pathname === '/address/zip'
        ? await lookupZip(payload.zip)
        : await verifyAddress(payload || {});

      return json({ ok: true, ...result }, 200, cors);
    }

    /* Whether an address can receive mail at all. Answers "unknown" rather
       than an error when the lookup does not come back, because a DNS query
       that timed out is not evidence against somebody's email address. */
    if (url.pathname === '/email/check') {
      if (request.method !== 'POST') {
        return json({ ok: false, error: 'Send this with POST.' }, 405, cors);
      }
      if (origin && !originAllowed(request, env)) {
        return json({ ok: false, error: 'Origin not allowed.' }, 403, cors);
      }

      let payload = {};
      try { payload = await request.json(); } catch (ignored) { /* empty */ }

      return json({ ok: true, ...(await checkEmail(payload.email)) }, 200, cors);
    }

    /* Emails a code, and checks it back. Nothing is stored: the code travels
       signed, and the signature is what the browser holds. */
    if (url.pathname === '/email/send-code' || url.pathname === '/email/verify-code') {
      if (request.method !== 'POST') {
        return json({ ok: false, error: 'Send this with POST.' }, 405, cors);
      }
      if (origin && !originAllowed(request, env)) {
        return json({ ok: false, error: 'Origin not allowed.' }, 403, cors);
      }

      let payload = {};
      try { payload = await request.json(); } catch (ignored) { /* empty */ }

      const address = normalizeEmail(payload.email);
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address)) {
        return json({ ok: false, error: 'That does not look like an email address.' }, 200, cors);
      }

      if (url.pathname === '/email/verify-code') {
        const typed = String(payload.code || '').replace(/\D/g, '');
        const result = await checkChallenge(env, address, typed, payload.challenge);
        if (!result.ok) {
          return json({
            ok: false,
            reason: result.reason,
            error: result.reason === 'expired'
              ? 'That code has expired. Send yourself a new one.'
              : 'That code is not right. Check the email and try again.'
          }, 200, cors);
        }
        return json({ ok: true, proof: await makeProof(env, address) }, 200, cors);
      }

      // No point mailing a code to a domain that cannot receive mail.
      const reachable = await checkEmail(address);
      if (reachable.checked && !reachable.deliverable) {
        return json({
          ok: false,
          error: 'That domain cannot receive mail, so the code would bounce.',
          domain: reachable.domain
        }, 200, cors);
      }

      const code = makeCode();
      const siteUrl = String(env.SITE_URL || 'https://www.nixoraservices.com').replace(/\/$/, '');

      try {
        await send(env, {
          to: address,
          replyTo: '',
          subject: code + ' is your Nixora Services verification code',
          html: renderEmail(codeEmail(env, code, siteUrl)),
          text: renderText(codeEmail(env, code, siteUrl))
        });
      } catch (error) {
        console.error('Verification code failed to send:', error && error.message);
        return json({
          ok: false,
          error: 'We could not send the code. Please try again in a moment.',
          detail: error && error.detail
        }, 200, cors);
      }

      return json({ ok: true, challenge: await makeChallenge(env, address, code) }, 200, cors);
    }

    if (url.pathname === '/selftest') {
      // ?send=1 posts one real message to the configured recipient. The
      // recipient never comes from the request, so this cannot be pointed at
      // anyone else.
      return json(await selftest(env, {
        send: url.searchParams.get('send') === '1',
        places: url.searchParams.get('places') === '1',
        sheet: url.searchParams.get('sheet') === '1'
      }), 200, cors);
    }

    if (request.method !== 'POST') {
      return json({
        ok: false,
        error: 'Send this form with POST.',
        build: BUILD,
        hint: 'Add /selftest to this URL to check the settings.'
      }, 405, cors);
    }

    if (origin && !originAllowed(request, env)) {
      const configured = allowedOrigins(env);
      console.error('Refused origin ' + origin + '. ALLOWED_ORIGINS holds: ' +
        (configured.length ? configured.join(', ') : '(nothing)'));
      return json({
        ok: false,
        error: 'This site is not on the endpoint\'s allowed list.',
        origin: normalizeOrigin(origin),
        allowed: configured
      }, 403, cors);
    }

    const declaredLength = Number(request.headers.get('Content-Length') || 0);
    if (declaredLength > MAX_BODY_BYTES) {
      return json({ ok: false, error: 'Submission too large.' }, 413, cors);
    }

    let form;
    try {
      form = await readForm(request);
    } catch (error) {
      return json({ ok: false, error: 'Could not read the submission.' }, 400, cors);
    }

    // Honeypot: bots fill in every field they find, people never see this one.
    // Answering 200 keeps them from working out that they were caught.
    if (String(form.get('_gotcha') || '').trim()) {
      return wantsJson(request)
        ? json({ ok: true }, 200, cors)
        : Response.redirect(env.SITE_URL + '/thank-you.html', 303);
    }

    const type = detectFormType(form);
    const to = recipient(env, type);
    if (!to || !env.FROM_EMAIL || !cleanKey(env.RESEND_API_KEY)) {
      console.error('Worker is missing TO_EMAIL, FROM_EMAIL or RESEND_API_KEY.');
      return json({ ok: false, error: 'The form endpoint is not configured.' }, 500, cors);
    }

    /* An application has to carry proof that its email was verified. The
       contact and review forms do not: those are people writing in, and a
       code in the way of an enquiry costs more than it saves. */
    if (type === 'application') {
      const proof = await checkProof(env, form.get('email'), form.get('Email Verified'));
      if (!proof.ok) {
        console.error('Application without a verified email:', proof.reason);
        return json({
          ok: false,
          error: proof.reason === 'expired'
            ? 'Your email verification has expired. Verify it again and resend.'
            : 'This application needs a verified email address.',
          reason: proof.reason
        }, 403, cors);
      }
    }

    const spec = buildSpec(form, type);
    const siteUrl = String(env.SITE_URL || 'https://www.nixoraservices.com').replace(/\/$/, '');
    const pageUrl = siteUrl + '/' + spec.page;

    spec.logoUrl = siteUrl + '/assets/img/mail-logo.png';
    spec.footer = `Sent from the ${escapeHtml(spec.formName)} at ` +
      `<a href="${escapeHtml(pageUrl)}" style="color:#054a8b;">nixoraservices.com</a>. ` +
      escapeHtml(spec.footerNote);
    spec.footerText = 'Sent from the ' + spec.formName + ' at ' + pageUrl + '. ' + spec.footerNote;

    try {
      await send(env, {
        to,
        replyTo: spec.replyTo,
        subject: spec.subject,
        html: renderEmail(spec),
        text: renderText(spec)
      });
    } catch (error) {
      console.error('Sending failed:', error && error.message);
      // The detail goes back to the page as well as to the log. It is the
      // mail service's own description of a misconfiguration, carrying no
      // credential, and it reaches only origins already on the allowed list —
      // which is to say the site's own pages. Leaving it in the log alone
      // meant the one person who could fix it had the hardest path to reading
      // it.
      return json({
        ok: false,
        error: 'The message could not be sent.',
        detail: error && error.detail ? error.detail : String(error && error.message || ''),
        from: env.FROM_EMAIL,
        to: to
      }, 502, cors);
    }

    // The email is the part that must not fail, and it has already gone.
    try {
      await appendToSheet(env, form, type);
    } catch (error) {
      console.error('Sheet append failed:', error && error.message);
    }

    return wantsJson(request)
      ? json({ ok: true }, 200, cors)
      : Response.redirect(siteUrl + '/thank-you.html', 303);
  }
};
